import Image from 'next/image'

import { Counter } from '@/components/library/motion/Counter'
import { AccentButton } from '@/components/library/primitives/AccentButton'
import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import {
  getAccentTone,
  padIndex,
  type AccentTone,
} from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type AboutStatsSplitStat = {
  value: number | string
  label: string
  prefix?: string
  suffix?: string
}

export type AboutStatsSplitProps = {
  title: string
  image: { src: string; alt: string }
  eyebrow?: string
  description?: string
  paragraphs?: readonly string[]
  stats?: readonly AboutStatsSplitStat[]
  pillars?: readonly { title: string; description: string }[]
  action?: { label: string; href: string }
  reverse?: boolean
  tone?: AccentTone
  className?: string
}

/** Seção institucional dividida: imagem com faixa de métricas e texto com pilares numerados. */
export function AboutStatsSplit({
  title,
  image,
  eyebrow,
  description,
  paragraphs = [],
  stats = [],
  pillars = [],
  action,
  reverse = false,
  tone = 'glow',
  className,
}: AboutStatsSplitProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'

  return (
    <section
      className={cn(
        'relative overflow-hidden',
        isGlow ? 'bg-[#0e0e0e]' : tone === 'industrial' ? 'bg-slate-50' : 'bg-slate-950',
        className,
      )}
    >
      <div className="grid lg:grid-cols-2">
        <div
          className={cn(
            'relative min-h-[18rem] sm:min-h-[22rem] lg:min-h-[32rem]',
            reverse && 'lg:order-2',
          )}
        >
          <Image
            src={image.src}
            alt={image.alt}
            fill
            sizes="(max-width: 1024px) 100vw, 50vw"
            className="object-cover"
          />
          <div
            className={cn(
              'absolute inset-0 bg-gradient-to-t to-transparent lg:bg-gradient-to-r lg:from-transparent',
              isGlow
                ? 'from-[#121212]/85 via-[#121212]/20 lg:via-[#121212]/10 lg:to-[#121212]/50'
                : 'from-slate-950/80 via-slate-950/20 lg:via-slate-950/10 lg:to-slate-950/40',
            )}
            aria-hidden
          />

          {stats.length ? (
            <dl
              className={cn(
                'absolute inset-x-0 bottom-0 grid border-t backdrop-blur-sm',
                isGlow ? 'border-[#493849] bg-[#121212]/75' : 'border-white/15 bg-slate-950/70',
              )}
              style={{ gridTemplateColumns: `repeat(${stats.length}, minmax(0, 1fr))` }}
            >
              {stats.map((stat, index) => (
                <div
                  key={stat.label}
                  className={cn(
                    'flex flex-col-reverse px-3 py-4 sm:px-5 sm:py-5',
                    index > 0 && cn('border-l', isGlow ? 'border-[#493849]' : 'border-white/15'),
                  )}
                >
                  <dt
                    className={cn(
                      'mt-1 text-[0.65rem] uppercase tracking-[0.18em] sm:text-[0.7rem]',
                      isGlow ? 'text-[#c1c1c1]' : 'text-slate-300',
                    )}
                  >
                    {stat.label}
                  </dt>
                  <dd className="text-xl font-semibold tracking-wide text-white sm:text-2xl lg:text-3xl">
                    {typeof stat.value === 'number' ? (
                      <Counter value={stat.value} prefix={stat.prefix} suffix={stat.suffix} />
                    ) : (
                      `${stat.prefix ?? ''}${stat.value}${stat.suffix ?? ''}`
                    )}
                  </dd>
                </div>
              ))}
            </dl>
          ) : null}
        </div>

        <div
          className={cn(
            'relative z-10 flex flex-col justify-center px-6 py-12 sm:px-10 lg:px-12 lg:py-16 xl:px-14',
            isGlow ? 'bg-[#121212]' : tone === 'industrial' ? 'bg-slate-50' : 'bg-slate-900',
          )}
        >
          <EyebrowHeading tone={tone} eyebrow={eyebrow} title={title} />
          {description ? (
            <p className={cn('mt-5 max-w-md text-base leading-relaxed', t.body)}>{description}</p>
          ) : null}
          {paragraphs.length ? (
            <div className={cn('mt-6 space-y-4 text-base leading-relaxed', t.body)}>
              {paragraphs.map((paragraph, index) => (
                <p key={index}>{paragraph}</p>
              ))}
            </div>
          ) : null}

          {pillars.length ? (
            <ul className={cn('mt-8 space-y-4 border-t pt-6', t.border)}>
              {pillars.map((pillar, index) => (
                <li key={pillar.title} className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1">
                  <span
                    className={cn('text-xs tracking-[0.2em]', isGlow ? 'text-[#ae89ff]' : t.accent)}
                  >
                    {padIndex(index)}
                  </span>
                  <div>
                    <p className={cn('text-sm font-semibold tracking-wide', t.strong)}>
                      {pillar.title}
                    </p>
                    <p className={cn('mt-1 text-sm leading-relaxed', t.muted)}>
                      {pillar.description}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          ) : null}

          {action ? (
            <div className="mt-8">
              <AccentButton href={action.href} tone={tone}>
                {action.label}
              </AccentButton>
            </div>
          ) : null}
        </div>
      </div>
    </section>
  )
}

'use client'

import { useRef } from 'react'
import { useGSAP } from '@/lib/hooks/useGSAP'
import { prefersReducedMotion, useReducedMotion } from './useReducedMotion'

export type CounterProps = {
  value: number
  from?: number
  duration?: number
  delay?: number
  decimals?: number
  locale?: string
  prefix?: string
  suffix?: string
  className?: string
  trigger?: 'mount' | 'scroll'
  formatter?: (value: number) => string
}

export function Counter({
  value,
  from = 0,
  duration = 1.5,
  delay = 0,
  decimals = 0,
  locale = 'pt-BR',
  prefix = '',
  suffix = '',
  className,
  trigger = 'scroll',
  formatter,
}: CounterProps) {
  const root = useRef<HTMLSpanElement>(null)
  const output = useRef<HTMLSpanElement>(null)
  const reduced = useReducedMotion()
  const safeValue = Number.isFinite(value) ? value : 0
  const safeFrom = Number.isFinite(from) ? from : 0
  const precision = Math.min(20, Math.max(0, Math.trunc(decimals)))
  const numberFormat = new Intl.NumberFormat(locale, {
    minimumFractionDigits: precision,
    maximumFractionDigits: precision,
  })
  const format = (current: number): string =>
    `${prefix}${formatter ? formatter(current) : numberFormat.format(current)}${suffix}`
  const finalText = format(safeValue)

  useGSAP(
    ({ gsap }) => {
      const element = root.current
      const text = output.current
      if (!element || !text) return

      if (reduced || prefersReducedMotion()) {
        text.textContent = finalText
        return
      }

      const state = { value: safeFrom }
      gsap.to(state, {
        value: safeValue,
        duration,
        delay,
        ease: 'power2.out',
        onStart: () => {
          text.textContent = format(safeFrom)
        },
        onUpdate: () => {
          text.textContent = format(state.value)
        },
        onComplete: () => {
          text.textContent = finalText
        },
        scrollTrigger:
          trigger === 'scroll'
            ? {
                trigger: element,
                start: 'top 90%',
                once: true,
              }
            : undefined,
      })

      return () => {
        text.textContent = finalText
      }
    },
    [
      delay,
      duration,
      finalText,
      formatter,
      locale,
      precision,
      prefix,
      reduced,
      safeFrom,
      safeValue,
      suffix,
      trigger,
    ],
    root,
  )

  return (
    <span ref={root} className={className} aria-label={finalText}>
      <span ref={output} aria-hidden="true">
        {finalText}
      </span>
    </span>
  )
}

'use client'

import { useEffect, useState } from 'react'

const QUERY = '(prefers-reduced-motion: reduce)'

export function prefersReducedMotion(): boolean {
  return typeof window !== 'undefined' && window.matchMedia(QUERY).matches
}

export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const media = window.matchMedia(QUERY)
    const update = (): void => setReduced(media.matches)

    update()
    media.addEventListener('change', update)
    return () => media.removeEventListener('change', update)
  }, [])

  return reduced
}

import type { MouseEventHandler, ReactNode } from 'react'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

import type { AccentTone } from './accentTones'

export type AccentButtonProps = {
  children: ReactNode
  href?: string
  tone?: AccentTone
  size?: 'md' | 'lg'
  icon?: ReactNode
  external?: boolean
  type?: 'button' | 'submit'
  disabled?: boolean
  onClick?: MouseEventHandler<HTMLElement>
  className?: string
}

const slideBase =
  'group relative inline-flex w-fit cursor-pointer items-center overflow-hidden rounded-sm font-semibold tracking-wide transition-all duration-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-60'

const slideSizes = {
  md: {
    root: 'h-12 p-1.5 ps-5 pe-14 text-sm hover:ps-14 hover:pe-5',
    icon: 'right-1.5 h-9 w-9 group-hover:right-[calc(100%-42px)]',
  },
  lg: {
    root: 'h-14 p-1 ps-6 pe-20 text-base hover:ps-20 hover:pe-6 md:text-lg',
    icon: 'right-1.5 h-11 w-11 group-hover:right-[calc(100%-50px)]',
  },
}

const toneClasses: Record<AccentTone, { root: string; icon: string }> = {
  glow: {
    root: 'inline-flex items-center justify-center gap-2 rounded-full border-2 border-[#7c39cf] bg-transparent px-4 py-2 font-semibold text-[#ae89ff] transition-[color,border-color,box-shadow,background-color] duration-300 hover:border-[#c642a5] hover:bg-gradient-to-r hover:from-[#86196b] hover:to-[#5327b3] hover:text-white hover:shadow-[0_0_8px_#c642a5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#c642a5] focus-visible:ring-offset-2 focus-visible:ring-offset-[#121212] disabled:pointer-events-none disabled:opacity-60',
    icon: '',
  },
  industrial: {
    root: 'bg-slate-900 text-white hover:bg-amber-500 hover:text-slate-950',
    icon: 'bg-white text-slate-900 group-hover:bg-slate-950 group-hover:text-white',
  },
  'industrial-dark': {
    root: 'bg-amber-500 text-slate-950 hover:bg-white',
    icon: 'bg-white text-slate-950 group-hover:bg-slate-950 group-hover:text-white',
  },
}

/** Botão de ação dos templates: contorno com gradiente (glow) ou ícone deslizante (industrial). */
export function AccentButton({
  children,
  href,
  tone = 'glow',
  size = 'md',
  icon,
  external,
  type = 'button',
  disabled,
  onClick,
  className,
}: AccentButtonProps) {
  const styles = toneClasses[tone]
  const isGlow = tone === 'glow'
  const resolvedIcon = icon ?? <ArrowUpRight className="h-4 w-4 shrink-0" aria-hidden />
  const classes = isGlow
    ? cn(styles.root, size === 'lg' && 'px-6 py-3 text-lg', className)
    : cn(slideBase, slideSizes[size].root, styles.root, className)

  const content = isGlow ? (
    <>
      {icon}
      {children}
    </>
  ) : (
    <>
      <span className="relative z-10 transition-colors duration-500">{children}</span>
      <span
        className={cn(
          'absolute flex items-center justify-center rounded-full transition-all duration-500 group-hover:rotate-12',
          slideSizes[size].icon,
          styles.icon,
        )}
        aria-hidden
      >
        {resolvedIcon}
      </span>
    </>
  )

  if (href) {
    const isExternal = external ?? /^(https?:|mailto:|tel:)/.test(href)
    if (isExternal) {
      return (
        <a
          href={href}
          className={classes}
          onClick={onClick}
          target={href.startsWith('http') ? '_blank' : undefined}
          rel={href.startsWith('http') ? 'noopener noreferrer' : undefined}
        >
          {content}
        </a>
      )
    }
    return (
      <Link href={href} className={classes} onClick={onClick}>
        {content}
      </Link>
    )
  }

  return (
    <button type={type} className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  )
}

import type { ReactNode } from 'react'

import { cn } from '@/lib/utils'

import { getAccentTone, type AccentTone } from './accentTones'

export type EyebrowHeadingProps = {
  title: ReactNode
  eyebrow?: ReactNode
  description?: ReactNode
  tone?: AccentTone
  align?: 'left' | 'center'
  layout?: 'stacked' | 'split'
  size?: 'md' | 'lg'
  titleAs?: 'h1' | 'h2' | 'h3'
  action?: ReactNode
  className?: string
}

const titleSizes = {
  md: 'text-3xl leading-[1.15] sm:text-4xl lg:text-[2.5rem]',
  lg: 'text-3xl leading-[1.12] sm:text-4xl md:text-5xl lg:text-[3.25rem]',
}

/** Cabeçalho de seção com linha de destaque, título temático e descrição opcional ao lado. */
export function EyebrowHeading({
  title,
  eyebrow,
  description,
  tone = 'glow',
  align = 'left',
  layout = 'stacked',
  size = 'md',
  titleAs: Title = 'h2',
  action,
  className,
}: EyebrowHeadingProps) {
  const t = getAccentTone(tone)
  const centered = align === 'center'
  const split = layout === 'split' && !centered

  const line = <span className={cn('h-px w-8 shrink-0', t.line)} aria-hidden />

  return (
    <div
      className={cn(
        split && 'flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between',
        centered && 'mx-auto max-w-3xl text-center',
        className,
      )}
    >
      <div className={cn(split ? 'max-w-2xl' : centered ? '' : 'max-w-3xl')}>
        {eyebrow ? (
          <div className={cn('mb-4 flex items-center gap-3', centered && 'justify-center')}>
            {line}
            <span
              className={cn('text-[0.65rem] font-medium uppercase tracking-[0.28em]', t.accent)}
            >
              {eyebrow}
            </span>
            {centered ? line : null}
          </div>
        ) : null}
        <Title className={cn(t.heading, titleSizes[size], centered && 'mx-auto')}>{title}</Title>
        {!split && description ? (
          <p
            className={cn(
              'mt-5 max-w-2xl text-base leading-relaxed md:text-lg',
              t.body,
              centered && 'mx-auto',
            )}
          >
            {description}
          </p>
        ) : null}
        {!split && action ? (
          <div className={cn('mt-8 flex flex-wrap gap-3', centered && 'justify-center')}>
            {action}
          </div>
        ) : null}
      </div>
      {split && (description || action) ? (
        <div className="max-w-md space-y-5">
          {description ? (
            <p className={cn('text-sm leading-relaxed lg:text-base', t.body)}>{description}</p>
          ) : null}
          {action}
        </div>
      ) : null}
    </div>
  )
}

'use client'

import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { useEffect, type DependencyList, type RefObject } from 'react'

let registered = false

function ensureGsapPlugins(): void {
  if (typeof window === 'undefined' || registered) return
  gsap.registerPlugin(ScrollTrigger)
  registered = true
}

export type GSAPTools = {
  gsap: typeof gsap
  ScrollTrigger: typeof ScrollTrigger
}

export type GSAPCallback = (tools: GSAPTools) => void | (() => void)

export function useGSAP(
  callback: GSAPCallback,
  deps: DependencyList = [],
  scope?: RefObject<Element | null>,
): void {
  useEffect(() => {
    if (typeof window === 'undefined') return

    ensureGsapPlugins()

    let dispose: void | (() => void)
    const context = gsap.context(() => {
      dispose = callback({ gsap, ScrollTrigger })
    }, scope?.current ?? undefined)

    return () => {
      dispose?.()
      context.revert()
    }

    // Dependencies are deliberately controlled by each animation consumer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
